/* folderMapper insertRootFolder */

    SELECT nextval('folder_tb_folder_id_seq')

INSERT INTO FOLDER_TB (folder_id, name, folder_type, owner_id, create_user_id, create_time, modify_user_id, modify_time,
parent_folder_id, render_sequence, uuid, status, folder_id_path, folder_name_path)
VALUES (#{folderId}, #{name}, #{folderType}, #{ownerId}, #{createUserId}, #{createTime}, #{modifyUserId}, #{modifyTime},
#{parentFolderId}, #{renderSequence}, #{uuid}, #{status},
        (select folder_id_path || #{folderId} || '/' from folder_tb where folder_id = #{parentFolderId}
        ),(
            select folder_name_path || #{name} || '/' from folder_tb where folder_id = #{parentFolderId}
        )
)

