mapper.select:
SELECT folder_id, name, create_user_id, create_time, folder_type, owner_id, parent_folder_id, uuid, folder_name_path FROM folder_tb WHERE folder_type = #{folderType} AND owner_id = (SELECT user_id FROM user_tb where uuid = #{userUuid}) AND
parent_folder_id is null
parent_folder_id = #{parentFolderId}
AND status = #{status}

SELECT folder.uuid, folder.name, folder.folder_type, folder.render_sequence,
      parent.uuid, folder.status
FROM folder_tb folder
join folder_tb parent on folder.parent_folder_id = parent.folder_id
WHERE parent_folder_id = #{parentFolderId}
AND status = #{status}
ORDER BY render_sequence ASC NULLS LAST, folder_id ASC
OFFSET #{offset} LIMIT #{limit}

SELECT folder_id, name, create_user_id, create_time, folder_type, owner_id, parent_folder_id, uuid, folder_name_path FROM folder_tb WHERE folder_type = #{folderType} AND owner_id = (SELECT team_id FROM team_tb where uuid = #{teamUuid}) AND
parent_folder_id is null
parent_folder_id = #{parentFolderId}
AND status = #{status}
